ANNOTATIONS = [
    (9, 'after', r'''PowerShell 安全分析：代码注入、下载摇篮、提权、动态命令名、COM 对象等。全部基于 AST——解析失败（valid=false）时任何单项检查都不命中，powershellCommandIsSafe 直接返回 ask。'''),
    (57, 'after', r'''isPowerShellExecutable 从全路径里抠基名：/usr/bin/pwsh、C:\Windows\...\powershell.exe、.\pwsh 都算。'''),
    (72, 'after', r'''PS 另类参数前缀：/（5.1 的 powershell.exe）、en-dash、em-dash、horizontal bar。PowerShell 的 tokenizer（SpecialCharacters.IsDash）与 powershell.exe 的 CommandLineParameterParser 都认这四种，Extent.Text 保留原字符——所以 Start-Process foo –Verb RunAs（en-dash）曾绕过裸 commandHasArgAbbreviation 检查。'''),
    (100, 'after', r'''psExeHasParamAbbreviation：把另类前缀归一成 - 再查缩写匹配，覆盖所有 PS 参数检查（不只 pwsh.exe 调用）。'''),
    (117, 'after', r'''Invoke-Expression/iex = eval，能执行任意代码。'''),
    (160, 'after', r'''动态命令名：& ${function:Invoke-Expression} 'payload'、& ('iex','x')[0]、& ('i'+'ex')——cmd.name 是字面 extent 文本，hasCommandNamed 匹配不上，运行时却求值成命令名执行。合法命令名永远是 StringConstantExpressionAst，所以白名单放行 StringConstant、其余全 ask（denylist 动态类型太脆：未知 AST 类型默认映射到 'Other'，=== 'Variable' 会漏）。'''),
    (180, 'after', r'''编码参数 -EncodedCommand/-e：恶意软件绕过安全工具的常用手法。'''),
    (205, 'after', r'''嵌套 PowerShell 进程：命令位出现任何 PS 可执行文件就拦——不只 -Command/-File。裸 pwsh 收 stdin（Get-Content x | pwsh）或位置脚本路径同样执行任意代码，且无显式 flag。'''),
    (223, 'after', r'''下载器名单：Invoke-WebRequest/Invoke-RestMethod/New-Object/Start-BitsTransfer（MITRE T1197）。'''),
    (264, 'after', r'''下载摇篮两级：管道内（IWR ... | IEX）按语句查，跨语句（$r = IWR ...; IEX $r.Content）查全部命令——跨语句场景 checkInvokeExpression 已拦，这里只是把警告消息写清楚。'''),
    (315, 'after', r'''独立下载工具（LOLBAS）：Start-BitsTransfer 恒拦（就是干传输的）；certutil 只在 -urlcache 时拦（裸 certutil 有很多正当证书管理用途，且 -urlcache 与 /urlcache 两种写法都查）；bitsadmin /transfer 同理。'''),
    (331, 'after', r'''Add-Type 运行时编译加载 .NET 代码。'''),
    (429, 'after', r'''New-Object -ComObject：WScript.Shell、Shell.Application、MMC20.Application、Schedule.Service、Msxml2.XMLHTTP 都自带执行/下载能力，不需要 IEX。枚举不完所有危险 ProgID，任何 -ComObject 都 ask。-com 是最小无歧义缩写（-co 在 5.1 里与 -Confirm 撞）。另外 checkTypeLiterals 只看得见 [bracket] 语法，New-Object System.Net.WebClient 把类型当字符串参数传、CLM 永不触发——这里抽 -TypeName（命名/冒号/位置 0）过 isClmAllowedType 补漏（attackVectors D4）。'''),
    (487, 'after', r'''-FilePath 向量：Invoke-Command/Start-Job/Start-ThreadJob/Register-ScheduledJob 带 -FilePath 跑脚本文件，树里没有 ScriptBlockAst，checkScriptBlockInjection 永不触发。位置参数也查——Start-Job script.ps1 的位置 0 绑 -FilePath；过度标记是 fail-safe（Start-Job -Name foo 的 foo 也是 StringConstant）。'''),
    (534, 'after', r'''ForEach-Object -MemberName：Get-Process | ForEach-Object -MemberName Kill 杀光进程，语义等价于 | % { $_.Method() } 但树里既无 ScriptBlockAst 也无 InvokeMemberExpressionAst。PS7+ 的位置参数也绑 -MemberName（MemberSet 参数集），扫全部参数。'''),
    (633, 'after', r'''Start-Process 两向量：-Verb RunAs 提权（UAC 弹窗）；目标是 PS 可执行文件——Start-Process pwsh -ArgumentList 里塞 -e <b64>，外层命令的 cmd.name 是 Start-Process，checkEncodedCommand/checkPwshCommandOrFile 全部看不见。-Verb:'RunAs' 的引号/反引号形态曾绕过旧正则，现在 structural（children 树）+ regex 双层。已知误报：-WorkingDirectory C:\projects\pwsh 的基名是 pwsh——Start-Process 本就不在白名单（恒 ask），结果只是 ask 不是 reject，认了。'''),
    (652, 'after', r'''安全脚本块消费者：Where/Sort/Select/Group/Format-*——喂给它们的脚本块只是谓词或投影。故意不含 foreach-object：它的块是任意脚本；getAllCommands 递归得到块内命令，但 AssignmentStatementAst 等非命令节点看不见。'''),
    (709, 'after', r'''脚本块注入：树里有脚本块 + 任一危险 cmdlet → ask；全是安全消费者 → 放行；出现不认识的命令 → ask。'''),
    (724, 'after', r'''子表达式 $() 能藏命令执行。'''),
    (741, 'after', r'''可展开字符串（双引号）里的内嵌表达式：$env:PATH、$(dangerous-command)。'''),
    (756, 'after', r'''splatting（@variable）把参数藏进变量。'''),
    (771, 'after', r'''停止解析符 --%：其后一切原样传给原生命令。'''),
    (786, 'after', r'''.NET 方法调用能碰系统 API。'''),
    (813, 'after', r'''CLM 类型字面量：微软 ConstrainedLanguage 只放行约 90 个被认为对不可信代码安全的原语/特性，名单外的一律 ask（Reflection.Assembly、IO.Pipes、Diagnostics.Process、InteropServices.Marshal……）。跑在 checkMemberInvocations 之后：那个广撒网（任何 ::Method/.Method()），这个给精确的「哪些类型」信号；纯类型转换 [int]$x 无方法调用，只命中这条。'''),
    (836, 'after', r'''Invoke-Item/ii 用默认处理器打开文件（Windows ShellExecute）：对 .exe/.ps1/.bat/.cmd 就是 RCE。没有安全变体——连打开 .txt 都可能调用接受参数的用户配置处理器，恒 ask。'''),
    (883, 'after', r'''计划任务持久化：Register-ScheduledTask 及 legacy schtasks.exe /create——活得比会话长的持久化，以前无任何提示。'''),
    (932, 'after', r'''环境变量操纵：Set-Item/New-Item 写 env: 作用域，或任何涉及 env 变量的赋值。'sc' 故意缺席——PS Core 7+ 上与 sc.exe 撞名。'''),
    (960, 'after', r'''模块加载：Import-Module 执行 .psm1 顶层脚本体，Install-Module/Save-Module 从任意仓库下载。通配允许规则 Import-Module:* 会让攻击者给的 .ps1 以用户权限执行——与 IEX 同级。NEVER_SUGGEST 从这份名单派生（UI 永不把它们作为通配建议），但用户手写允许规则时由这里独立把门。'''),
    (1000, 'after', r'''运行期状态操纵：Set-Alias Get-Content Invoke-Expression 之后任何 Get-Content $x 都执行任意代码；Set-Variable PSDefaultParameterValues 改 pathspec 默认值，改变之后每个 cmdlet 的行为。静态验证不了「未来所有命令解析」，恒 ask。'''),
    (1029, 'after', r'''WMI 进程派生：Invoke-WmiMethod -Class Win32_Process -Name Create -ArgumentList "cmd /c ..." 完全绕过 checkStartProcess。-Class/-MethodName 接受任意字符串，盯着 Win32_Process 会漏 -Class $x，一律 ask（security finding #34）。'''),
    (1079, 'after', r'''检查器链表——顺序即优先级，第一个 ask 胜出。'''),
    (1090, 'after', r'''主入口：解析失败直接 ask（安全默认），否则依序跑全部检查。'''),
]
